const crypto = require('crypto');

const secret = $env.AVITO_WEBHOOK_SECRET || '';
const rawBody = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data.data, 'base64')
  : Buffer.from(JSON.stringify($input.first().json.body || {}), 'utf-8');

const headers = $input.first().json.headers || {};
const signatureHeader = (headers['x-avito-messenger-signature'] || '').toLowerCase();

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

let signatureValid = false;
try {
  signatureValid = signatureHeader.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(signatureHeader, 'utf-8'), Buffer.from(expected, 'utf-8'));
} catch (e) {
  signatureValid = false;
}

const payload = ($input.first().json.body || {}).payload || {};
const value = payload.value || {};

return [{
  json: {
    signatureValid,
    chatId: value.chat_id,
    userId: value.user_id,
    authorId: value.author_id,
    itemId: value.item_id,
    messageText: value.content?.text || '',
    messageType: value.type,
    raw: $input.first().json.body
  }
}];

const sigData = $('Code: проверка подписи HMAC').first().json;
const item = $('HTTP: карточка объявления').first().json;
const history = $('HTTP: история чата (messenger:read)').first().json;

const messages = (history.messages || history.content?.messages || [])
  .slice()
  .reverse();

const transcript = messages.map(m => {
  const who = String(m.author_id) === String(sigData.authorId) ? 'Клиент' : 'Я (владелец/бот)';
  const text = m.content?.text || m.content?.message?.text || '';
  return `${who}: ${text}`;
}).join('\n');

const context = [
  `Объявление: ${item.title || '(без названия)'}`,
  `Описание (фрагмент): ${(item.description || '').slice(0, 600)}`,
  '',
  'История диалога (последние сообщения, от старых к новым):',
  transcript,
  '',
  `Новое сообщение клиента: ${sigData.messageText}`
].join('\n');

return [{
  json: {
    ...sigData,
    context,
    lastClientMessage: sigData.messageText
  }
}];

