const ctx = $('Code: собрать контекст для Claude').first().json;
const claude = $input.first().json;
const raw = (claude.content && claude.content[0] && claude.content[0].text) || '';

let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = {
    reply: 'Спасибо за сообщение! Передал задачу владельцу — он посмотрит и вернётся с ответом.',
    escalate: true,
    reason: 'fallback: не удалось разобрать ответ модели как JSON'
  };
}

return [{
  json: {
    ...ctx,
    reply: parsed.reply,
    escalate: !!parsed.escalate,
    escalateReason: parsed.reason || ''
  }
}];

