const THRESHOLD_HOURS = Number($env.FOLLOWUP_HOURS_THRESHOLD || 20);
const nowMs = Date.now();

const store = $getWorkflowStaticData('global');
store.remindedChats = store.remindedChats || {};

const chats = ($input.first().json.chats || []);
const userId = $env.AVITO_USER_ID;

const toRemind = chats.filter(chat => {
  const last = chat.last_message || {};
  const lastFromOwner = String(last.author_id) === String(userId);
  const updatedMs = (chat.updated || 0) * 1000;
  const hoursSilent = (nowMs - updatedMs) / (1000 * 60 * 60);
  const alreadyReminded = !!store.remindedChats[chat.id];
  return lastFromOwner && hoursSilent >= THRESHOLD_HOURS && !alreadyReminded;
});

return toRemind.map(chat => ({
  json: {
    chatId: chat.id,
    userId
  }
}));

